using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;
public static class Timber195Checks{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence195");const string Folder="Assets/Imported195b",Id="mine_timber_frame";
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static MineTimberV1.Data Clone(MineTimberV1.Data d)=>JsonUtility.FromJson<MineTimberV1.Data>(JsonUtility.ToJson(d));
 static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.13f,.14f,.15f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;}
 static GameObject Prop(string id){var p=AssetDatabase.LoadAssetAtPath<GameObject>((id==Id||id.StartsWith("mine_rail_")?Folder:"Assets/Imported192-valid")+"/small-"+id+".prefab");Check(p,"prefab "+id);return(GameObject)PrefabUtility.InstantiatePrefab(p);}
 static Camera Cam(){var c=new GameObject("offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.045f,.05f,.055f);c.fieldOfView=45;c.nearClipPlane=.03f;return c;}
 static void Shot(Camera c,string name){var t=Shared117Review.Image(c,1280,720);File.WriteAllBytes(Path.Combine(Out,name+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}
 public static void Run(){Directory.CreateDirectory(Out);try{
  Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  var input=Path.Combine(Root,"Input195");var d=JsonUtility.FromJson<MineTimberV1.Data>(File.ReadAllText(Path.Combine(input,"timber.json")));Check(MineTimberV1.Optional(d)!=null,"valid optional");Check(MineTimberV1.Optional(null)==null,"missing optional");
  var bad=Clone(d);bad.version=9;Check(MineTimberV1.Optional(bad)==null,"invalid version fallback");bad=Clone(d);bad.assets[0].positions[0]=float.NaN;Check(MineTimberV1.Optional(bad)==null,"nonfinite fallback");bad=Clone(d);bad.assets[0].triangles[0]=999999;Check(MineTimberV1.Optional(bad)==null,"indices fallback");
  var old=SmallPropsV1.Read(Path.Combine(Root,"Input187/small_props.json"));Check(old.mineTimberV1==null&&old.assets.Length==43&&old.mineCartV1!=null&&old.mineCobwebV1!=null,"existing data without extension retained");
  var data=new SmallPropsV1.Data{mineRailsV1=MineRailsV1.Optional(JsonUtility.FromJson<MineRailsV1.Data>(File.ReadAllText(Path.Combine(input,"rails.json")))) ,mineTimberV1=d};
  Check(!AssetDatabase.IsValidFolder(Folder),"fresh output");AssetDatabase.CreateFolder("Assets","Imported195b");var root=new GameObject("timber195");var prefabs=new Dictionary<string,GameObject>();MineRailsV1.Build(input,Folder,root.transform,prefabs,data);Check(MineTimberV1.Build(input,Folder,root.transform,prefabs,data)==1,"formal timber placement");Check(prefabs.Count==4,"three rails plus timber");
  var p=prefabs[Id];var mesh=p.GetComponent<MeshFilter>().sharedMesh;var mat=p.GetComponent<Renderer>().sharedMaterial;Check(mesh.triangles.Length/3==364&&mesh.tangents.Length==mesh.vertexCount,"geometry tangents");Check(mat==prefabs["mine_rail_straight"].GetComponent<Renderer>().sharedMaterial,"same material actual reference");Check(mat.shader.name=="Universal Render Pipeline/Lit"&&!ShaderUtil.ShaderHasError(mat.shader),"standard shader");Check(p.GetComponents<MeshCollider>().Length==1&&p.GetComponents<Collider>().Length==1,"combined cylinder mesh proxy");
  var cm=p.GetComponent<MeshCollider>().sharedMesh;Check(cm.vertexCount==100&&cm.triangles.Length/3==192,"two24-sided cylinder islands");var cv=cm.vertices;foreach(var v in cv)Check(Mathf.Abs(v.x)>.939f&&v.y>=0&&v.y<=2.861f,"central passage remains open");var ct=cm.triangles;for(int i=0;i<ct.Length;i+=3)Check(Mathf.Sign(cv[ct[i]].x)==Mathf.Sign(cv[ct[i+1]].x)&&Mathf.Sign(cv[ct[i]].x)==Mathf.Sign(cv[ct[i+2]].x),"no collider bridge across passage");
  Check(p.GetComponentsInChildren<Light>().Length==0,"no lights");
  var sig=ColliderSnapshot109.Capture(root);var save=PrefabUtility.SaveAsPrefabAsset(root,Folder+"/placed.prefab");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(save);Check(sig==ColliderSnapshot109.Capture(root),"prefab collider persistence");EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),Folder+"/reload.unity");Empty();EditorSceneManager.OpenScene(Folder+"/reload.unity");root=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None).Single(x=>x.name=="placed");Check(sig==ColliderSnapshot109.Capture(root),"scene collider persistence");Check(root.GetComponentsInChildren<Renderer>().All(x=>x.sharedMaterial==mat),"scene material shared");
  var noRail=new Dictionary<string,GameObject>();Check(MineTimberV1.Build(input,Folder,root.transform,noRail,data)==0&&noRail.Count==0,"missing rail atlas fallback");
  Studio();Field();Load();AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"formalGenerated\":4,\"newTarget\":1,\"triangles\":364,\"newTextures\":0,\"newMaterials\":0,\"prefabSceneReload\":true,\"oldDataRead\":true,\"all75Generated\":false,\"missingInvalidOptionalFallback\":true,\"noRailAtlasFallback\":true,\"player\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Studio(){Empty();var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.color=new Color(.25f,.23f,.19f);floor.GetComponent<Renderer>().sharedMaterial=fm;var sun=new GameObject("sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.3f;sun.shadows=LightShadows.Soft;Prop(Id);for(int i=-1;i<2;i++){var rail=Prop("mine_rail_straight");rail.transform.position=new Vector3(0,0,i*2);}var cart=Prop("minecart_loaded");cart.transform.position=new Vector3(0,.14f,-1);var camera=Cam();foreach(var view in new[]{"normal","close","back","opposite","dark"}){sun.transform.rotation=Quaternion.Euler(45,view=="opposite"?150:-30,0);sun.intensity=view=="dark"?.12f:1.3f;RenderSettings.ambientLight=view=="dark"?new Color(.025f,.03f,.035f):new Color(.13f,.14f,.15f);camera.transform.position=view=="normal"?new Vector3(0,9,-6.3f):view=="back"?new Vector3(-3,3,5):new Vector3(3,3.1f,-5);camera.transform.LookAt(new Vector3(0,1.15f,0));Shot(camera,"studio-"+view);}}
 static void Field(){Empty();RenderSettings.ambientLight=new Color(.08f,.09f,.10f);var result=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Timber195");Check(result.built,"existing formal mine");var c=Cam();var hero=new GameObject("camera anchor").transform;hero.position=new Vector3(12,0,10.5f);var cut=result.root.GetComponent<MapTunnels.MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=c;var timber=Prop(Id);timber.transform.position=new Vector3(12,0,10.5f);var cart=Prop("minecart_loaded");cart.transform.position=new Vector3(12,.14f,9.5f);for(int i=0;i<3;i++){var rail=Prop("mine_rail_straight");rail.transform.position=new Vector3(12,0,13.5f-i*2);}foreach(var v in new[]{"normal","close","reverse"}){var target=timber.transform.position+Vector3.up*1.2f;c.transform.position=v=="normal"?hero.position+new Vector3(0,9,-6.3f):target+(v=="close"?new Vector3(.25f,.5f,-3):new Vector3(-.25f,.5f,3));c.transform.LookAt(v=="normal"?hero.position+Vector3.up*.5f:target);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);Shot(c,"mine-"+v);}File.WriteAllText(Path.Combine(Out,"field.json"),"{\"input\":\"Input123Mine\",\"width\":2.4,\"height\":2.8,\"originalUnchanged\":true,\"lightsUnchanged\":true,\"manualFrameAt\":[12,0,10.5]}");}
 static void Load(){var rows=new List<string>();foreach(int count in new[]{9,225}){Empty();var root=new GameObject("many");int side=count==9?3:15;for(int i=0;i<count;i++){var p=Prop(Id);p.transform.SetParent(root.transform,false);p.transform.position=new Vector3((i%side-side/2)*3,0,(i/side-side/2)*3);}var rs=root.GetComponentsInChildren<Renderer>();var meshes=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).Distinct().ToArray();var mats=rs.Select(x=>x.sharedMaterial).Distinct().ToArray();Check(meshes.Length==1&&mats.Length==1,"shared mesh material");var c=Cam();c.transform.position=new Vector3(0,30,-26);c.transform.LookAt(Vector3.zero);var rt=new RenderTexture(640,360,24);rt.Create();c.targetTexture=rt;for(int pass=0;pass<3;pass++)c.Render();var planes=GeometryUtility.CalculateFrustumPlanes(c);rows.Add("{\"placed\":"+count+",\"visible\":"+rs.Count(r=>GeometryUtility.TestPlanesAABB(planes,r.bounds))+",\"meshes\":1,\"materials\":1,\"textures\":3,\"meshBytes\":"+UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(meshes[0])+"}");c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(Out,"load.json"),"{\"gpuMeasured\":false,\"rows\":["+string.Join(",",rows)+"]}");}
}
